std::string decodeString(std::string source)
{
	std::string result;

	size_t i = 0;
	while (i < source.size())
	{
		char c = source[i++];
		if (c == '&')
		{
			std::string entity;
			while (i < source.size())
			{
				c = source[i++];
				if (c == ';')
					break;
				entity += c;
			}

			if (entity == "lt")
				result += '<';
			else if (entity == "gt")
				result += '>';
			else if (entity == "amp")
				result += '&';
			else if (entity == "quot")
				result += '"';
			else if (entity == "apos")
				result += '\'';
			else if (entity[0] == '#')
				result += atoi(entity.substr(1).c_str());
			else
				RBXASSERT(0);
		}
		else
		{
			result += c;
		}
	}

	return result;
}

