			break;
	}

	bool inQuotes = false;
	size_t j = i;

	for (; j < contents.size(); j++)
	{
		if (contents[j] == '"')
		{
			inQuotes = !inQuotes;
		}
		else if (!inQuotes && whitespaces.data[contents[j]])
		{
			break;
