	{
	}

	XmlNameValuePair(const RBX::Name& tag)
		: tag(tag),
		  valueType(NONE)
	{
	}
public:
	~XmlNameValuePair()
	{
		clearValue();
	}

public:
	const RBX::Name& getTag() const
	{
		return tag;
	}

	bool isValueEmpty() const;

	bool isValueEqual(RBX::InstanceHandle) const;
	bool isValueEqual(const RBX::Name*) const;
	bool isValueEqual(bool) const;
